/* VISUALZI Studio · Fast library previews v19.
 * Preview frames are baked from existing VISUALZI QA footage, not render engines.
 * Editor, MIDI, audio analysis, user presets and export are unchanged.
 * Default: static thumbnail; desktop mouse hover: 8-frame CSS motion loop.
 */
(() => {
  'use strict';
  if (typeof Home === 'undefined' || typeof App === 'undefined' || !Array.isArray(Home.cards)) return;
  const DATA = {"midi":"","retro":"","caustic":"","contour":"","dust":"","spatial":"","volume":"","dancer":"","grid":"","pads":"","scope":"","tracker":""};
  const css = `
    .vz-lite-thumb {
      position:absolute;inset:0;display:block;width:100%;height:100%;
      background-repeat:no-repeat;background-size:800% 100%;
      background-position:0 0;pointer-events:none;z-index:0;
    }
    .card-stage>.card-open {z-index:2;}
    @media (hover:hover) and (prefers-reduced-motion:no-preference) {
      .card:hover .vz-lite-thumb, .card:focus-visible .vz-lite-thumb {
         animation: vz-lite-frames 1.25s steps(7,end) infinite;
      }
    }
    @keyframes vz-lite-frames { from {background-position:0 0;} to {background-position:100% 0;} }
  `;
  const style=document.createElement('style');
  style.textContent=css;
  document.head.appendChild(style);
  const originalFrame=Home.frame;
  // Critical: gallery must never create video/audio/WebGL engines. They live only in the workspace.
  Home.frame=function fastHomeFrame(){};
  Home.litePreview=true;
  const setImages=()=>{
     for(const c of Home.cards) {
       if(c.stage.querySelector('.vz-lite-thumb'))continue;
       const data=DATA[c.E.id] || DATA.retro;
       if(!data)continue;
       const thumb=document.createElement('span');
       thumb.className='vz-lite-thumb';
       thumb.style.backgroundImage='url("data:image/webp;base64,'+data+'")';
       thumb.setAttribute('aria-hidden','true');
       c.stage.insertBefore(thumb,c.stage.firstChild);
     }
  };
  setImages();
  // Hooks only gallery rebuilding; workspace visuals and export remain untouched.
  const originalBuild=Home.build;
  Home.build=function(...args){
    const result=originalBuild.apply(this,args);
    setImages();
    return result;
  };
  // Stay idle in background tabs: CSS animations also suspend naturally with display:none.
  document.addEventListener('visibilitychange',()=>{
    document.documentElement.classList.toggle('vz-page-hidden',document.hidden);
  });
  console.info('[VISUALZI] Lightweight library active: '+Object.keys(DATA).length+' poster animations; 0 home engines.');
})();